272	  const ePos = s.indexOf('e');
273	  let mantissa;
274	  let exp;
275	  if (ePos >= 0) {
276	    mantissa = s.slice(0, ePos);
277	    exp = Number(s.slice(ePos + 1));
278	  } else {
279	    mantissa = s;
280	    exp = 0;
281	  }
282	  const dotPos = mantissa.indexOf('.');
283	  let intPart;
284	  let fracPart;
285	  if (dotPos >= 0) {
286	    intPart = mantissa.slice(0, dotPos);
287	    fracPart = mantissa.slice(dotPos + 1);
288	  } else {
289	    intPart = mantissa;
290	    fracPart = '';
291	  }
292	  let digits;
293	  let decpt;
294	  if (intPart === '0' || intPart === '') {
295	    // value < 1: skip leading zeros of the fraction
296	    let zeros = 0;
297	    while (zeros < fracPart.length && fracPart.charAt(zeros) === '0') zeros++;
