312	export function pythonFloatRepr(value) {
313	  if (Number.isNaN(value)) return 'nan';
314	  if (value === Infinity) return 'inf';
315	  if (value === -Infinity) return '-inf';
316	  if (value === 0) return isNegativeZero(value) ? '-0.0' : '0.0';
317	
318	  const sign = value < 0 ? '-' : '';
319	  const { digits, decpt } = shortestDigits(Math.abs(value));
320	
321	  if (decpt > 16 || decpt <= -4) {
322	    const e = decpt - 1;
323	    const absE = Math.abs(e);
324	    const expStr = (e < 0 ? '-' : '+') + (absE < 10 ? '0' + String(absE) : String(absE));
325	    const mantissa = digits.length > 1
326	      ? digits.charAt(0) + '.' + digits.slice(1)
